const keys = Object.entries(STATIC_MODEL_REGISTRY).flatMap(([channel, provider]) => provider.models.map(model => channel + '/' + model.id))
MODEL_AUDIT_DATA.rows = { ...MODEL_AUDIT_DATA.extraRows, ...Object.fromEntries(keys.flatMap((key, i) => MODEL_AUDIT_DATA.rows[i] ? [[key, MODEL_AUDIT_DATA.rows[i]]] : [])) }
delete MODEL_AUDIT_DATA.extraRows
export function auditedModelSpecs(channel, id) {
    const row = MODEL_AUDIT_DATA.rows[channel + '/' + id];
    const result = {};
    MODEL_AUDIT_DATA.fields.forEach((field, index) => {
        const fact = row ? MODEL_AUDIT_DATA.facts[row[index]] : [null, 'unknown', null, null];
        result[field] = { value: fact[0], state: fact[1], provenance: fact[2], sourceUrl: fact[3] === null ? null : MODEL_AUDIT_DATA.sources[fact[3]], verifiedAt: row ? MODEL_AUDIT_DATA.verifiedAt : null };
    });
    const details = MODEL_AUDIT_DATA.details?.[channel + '/' + id];
    if (details?.unknownInputModalities)
        result.inputModalities.unknownModalities = details.unknownInputModalities;
    for (const [field, values] of Object.entries(details?.unsupportedModalities || {}))
        result[field].unsupportedModalities = values;
    for (const field of details?.suppressFallback || [])
        result[field].suppressFallback = true;
    return { fields: result, unverified: !row || row[4] === 1, verifiedAt: row ? MODEL_AUDIT_DATA.verifiedAt : null, sourceUrl: row && row[5] !== null ? MODEL_AUDIT_DATA.sources[row[5]] : null, sourceUrls: details?.sourceUrls || [], sourceLinks: details?.sourceLinks || [], note: details?.note || '' };
}
// Tombstones preserve exact identities for messages and explicit replacement choices, never catalog entries.
export function removedModel(channel, id, now = Date.now()) {
    const key = channel + '/' + String(id).trim();
    const removed = MODEL_AUDIT_DATA.removed?.[key];
    if (removed)
        return removed;
    const notice = MODEL_AUDIT_DATA.notices[key];
    return notice && now >= Date.parse(notice.stopDate)
        ? { ...notice, replacementApiId: notice.replacement } : null;
}
export function modelDisplayName(channel, id) {
    const key = channel + '/' + id;
    const row = MODEL_AUDIT_DATA.removed?.[key] || MODEL_AUDIT_DATA.notices[key];
    if (row?.displayName)
        return row.displayName;
    const replacement = Object.entries({ ...MODEL_AUDIT_DATA.removed, ...MODEL_AUDIT_DATA.notices })
        .find(([key, row]) => key.startsWith(channel + '/') && (row.replacementApiId || row.replacement) === id)?.[1];
    return replacement?.replacementDisplayName || id;
}
export function removedModelHint(channel, id, now = Date.now()) {
    const removed = removedModel(channel, id, now);
    return removed ? `${removed.displayName}：原型号已不可用，请重新选择。${removed.replacementApiId ? `推荐：${removed.replacementDisplayName}` : ''}` : '';
}
// Date-only notices take effect at the start of the stated UTC calendar day.
// Serverless notices apply only to the Fireworks adapter used by this product.
export function auditedModelLifecycle(channel, id, now = Date.now()) {
    const notice = MODEL_AUDIT_DATA.notices[channel + '/' + String(id).trim()];
    if (!notice || notice.scope === 'serverless' && channel !== 'fireworks')
        return null;
    const elapsed = now >= Date.parse(notice.stopDate);
    if (elapsed)
        return null;
    const replacement = notice.replacement || null;
    const stopLabel = notice.stopDate.includes('T') ? notice.stopDate.replace('T', ' ').replace(':00+08:00', ' (UTC+8)') : notice.stopDate;
    return { ...notice, replacement, state: 'scheduled', label: '将下线', blocked: false, message: `将于${stopLabel}下线${replacement ? `；可改选 ${notice.replacementDisplayName}` : ''}` };
}
export function assertAuditedModelAvailable(channel, id, now = Date.now()) {
    const removed = removedModel(channel, id, now);
    if (removed)
        throw Object.assign(new Error(`模型 ${removedModelHint(channel, id, now)}`), {
            businessCode: 'MODEL_UNAVAILABLE', code: 'MODEL_UNAVAILABLE',
            statusCode: 400, replacement: removed.replacementApiId, sourceUrl: removed.sourceUrl,
            requestState: 'not_sent', localInputFailure: true, retryable: false,
        });
}
export function withModelAudit(channel, model, now = Date.now()) {
    const lifecycle = auditedModelLifecycle(channel, model.id, now);
    return { ...model, auditChannel: channel, auditSpecifications: auditedModelSpecs(channel, model.id), auditLifecycle: lifecycle,
        ...(removedModel(channel, model.id, now) ? { selectable: false, disabledReason: removedModelHint(channel, model.id, now) } : {}) };
}
export function assertModelLibraryAdditions(next, previous, now = Date.now(), intent = 'save') {
    // A first sync or explicit import restores historical identities. Availability
    // is still enforced at selection/execution and at explicit user additions.
    if (intent === 'import' || !previous && intent !== 'add')
        return;
    for (const model of next.models || []) {
        const channel = next.connections?.find((item) => item.id === model.connectionId)?.provider;
        const retained = previous?.models?.some((old) => old.id === model.id && old.connectionId === model.connectionId && old.modelId === model.modelId
            && previous.connections?.find((item) => item.id === old.connectionId)?.provider === channel);
        if (!retained)
            assertAuditedModelAvailable(channel, model.modelId, now);
    }
}
